using DadoHome.Api.Pos;
using Microsoft.EntityFrameworkCore;
namespace DadoHome.Api.Data;
public class DadoDbContext(DbContextOptions<DadoDbContext> options):DbContext(options){public DbSet<Product> Products=>Set<Product>();public DbSet<Category> Categories=>Set<Category>();public DbSet<Customer> Customers=>Set<Customer>();public DbSet<StaffUser> StaffUsers=>Set<StaffUser>();public DbSet<Order> Orders=>Set<Order>();public DbSet<OrderItem> OrderItems=>Set<OrderItem>();public DbSet<ProductReturn> ProductReturns=>Set<ProductReturn>();public DbSet<Wallet> Wallets=>Set<Wallet>();public DbSet<WalletEntry> WalletEntries=>Set<WalletEntry>();public DbSet<Payment> Payments=>Set<Payment>();public DbSet<PaymentEvent> PaymentEvents=>Set<PaymentEvent>();public DbSet<Refund> Refunds=>Set<Refund>();public DbSet<AuditLog> AuditLogs=>Set<AuditLog>();protected override void OnModelCreating(ModelBuilder b){b.ConfigurePos();b.Entity<Category>().HasIndex(x=>new{x.ParentId,x.Name}).IsUnique();b.Entity<Customer>().HasIndex(x=>x.Phone).IsUnique();b.Entity<StaffUser>().HasIndex(x=>x.Phone).IsUnique();b.Entity<Wallet>().HasIndex(x=>x.CustomerId).IsUnique();b.Entity<PaymentEvent>().HasIndex(x=>x.EventId).IsUnique();b.Entity<WalletEntry>().HasIndex(x=>x.ExternalId).IsUnique();b.Entity<WalletEntry>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<Payment>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<Refund>().Property(x=>x.Amount).HasPrecision(18,2);b.Entity<Product>().Property(x=>x.Price).HasPrecision(18,2);b.Entity<Order>().Property(x=>x.Subtotal).HasPrecision(18,2);b.Entity<Order>().Property(x=>x.DeliveryFee).HasPrecision(18,2);b.Entity<Order>().Property(x=>x.Total).HasPrecision(18,2);b.Entity<OrderItem>().Property(x=>x.UnitPrice).HasPrecision(18,2);b.Entity<ProductReturn>().HasIndex(x=>x.IdempotencyKey).IsUnique();}}
