public class Wallet{public Guid Id{get;set;}public Guid CustomerId{get;set;}public string Currency{get;set;}="TJS";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}public class WalletEntry{public Guid Id{get;set;}public Guid WalletId{get;set;}public Guid? OrderId{get;set;}public decimal Amount{get;set;}public string Type{get;set;}="";public string Status{get;set;}="Pending";public string ExternalId{get;set;}="";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}public class Payment{public Guid Id{get;set;}public Guid OrderId{get;set;}public Guid CustomerId{get;set;}public decimal Amount{get;set;}public string Method{get;set;}="";public string Provider{get;set;}="";public string Status{get;set;}="Created";public string ProviderTransactionId{get;set;}="";public DateTime CreatedAt{get;set;}}public class PaymentEvent{public Guid Id{get;set;}public string EventId{get;set;}="";public Guid PaymentId{get;set;}public string Status{get;set;}="";public DateTime CreatedAt{get;set;}}public class Refund{public Guid Id{get;set;}public Guid PaymentId{get;set;}public decimal Amount{get;set;}public string Reason{get;set;}="";public string Status{get;set;}="Created";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}public class AuditLog{public Guid Id{get;set;}public string ActorId{get;set;}="";public string Role{get;set;}="";public string Action{get;set;}="";public string Entity{get;set;}="";public string EntityId{get;set;}="";public DateTime CreatedAt{get;set;}=DateTime.UtcNow;}


